SELECT c.*,c.class_id AS classid FROM t_contents c JOIN t_oneshot m ON m.id=c.class_id
WHERE m.site_project_id=#{siteId} AND (c.site_project_id=#{siteId} OR c.site_project_id IS NULL) AND c.class_id=#{menuId} AND c.id>#{after}
ORDER BY c.id LIMIT #{limit} FOR UPDATE

