UPDATE t_contents SET public_search_text=CASE id
WHEN #{row.id} THEN #{row.text}
ELSE public_search_text END
WHERE (site_project_id=#{siteId} OR site_project_id IS NULL) AND class_id=#{menuId}
AND EXISTS(SELECT 1 FROM t_oneshot m WHERE m.id=#{menuId} AND m.site_project_id=#{siteId}) AND id IN
#{row.id}
